CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,owner INTEGER NOT NULL,object_key TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS media_owner_idx ON media(owner);
CREATE TABLE IF NOT EXISTS content_reports(id INTEGER PRIMARY KEY AUTOINCREMENT,by_id INTEGER NOT NULL,kind TEXT NOT NULL,item_id INTEGER NOT NULL,reason TEXT,ts INTEGER NOT NULL,UNIQUE(by_id,kind,item_id));
